#[tokio::test]
async fn support_reply_templates_get_options_encodes_query_params() {
    let server = MockServer::start().await;
    Mock::given(method("GET"))
        .and(path_matcher("/v2/support-reply-templates/options"))
        .respond_with(ResponseTemplate::new(200).set_body_string(include_str!("fixtures/sdk_get_support_reply_template_options_response_value_200_application_json.json")))
        .mount(&server)
        .await;
    let client = common::test_client(&server).await;
    let params = sellapp::resources::support_reply_templates::GetOptionsParams {
        requested_placeholders: Some(vec!["foo".to_string(), "bar".to_string()]),
        ..Default::default()
    };
    let _ = client.support_reply_templates().get_options(params).await;
    let received = server.received_requests().await.expect("recorded requests");
    let request = received.first().expect("at least one request");
    let query = request.url.query().unwrap_or("");
    assert!(
        query.contains("requested_placeholders%5B%5D=foo&requested_placeholders%5B%5D=bar"),
        "expected query to contain {:?}, got {:?}",
        "requested_placeholders%5B%5D=foo&requested_placeholders%5B%5D=bar",
        query
    );
}
